<script setup lang="ts">
import { Text } from '@/shared/ui/text/paragraph';
import { RouterLink } from 'vue-router';
import { useStore } from 'vuex';
import { onMounted, computed } from 'vue';

const store = useStore();
onMounted(() => {
    store.dispatch('blogs/fetchBlog');
});

const blogsData = computed(() =>
    store.state.blogs?.blogData?.filter((item: any) => item.subject === 'Блог молока')
);
</script>

<template>
    <div class="project-item" v-for="item in blogsData" :key="item.id">
        <RouterLink :to="`${item.slug}/`" class="link">
            <div class="image">
                <img :src="item.image" :aria-label="`${item.name}`" />
            </div>
            <Text tagName="p" size="m" color="accent" class="category">
                {{ item.category }}
            </Text>
            <Text tagName="p" size="l" color="dark-first" class="title">
                {{ item.title }}
            </Text>
        </RouterLink>
    </div>
</template>

<style lang="scss" scoped>
@import './style.scss';
</style>
